import { describe, expect, it } from "vitest";
import { splitReport } from "./reportSections";

const REPORT = `# Post-mortem: demo (seed 1)

**Incident 00:30–00:52 · up to 47 % below the fault-free twin**

The C289 jam caused 70 % of the delay.
The best fix is to send chute C289's destination to C269: it would have saved 83 %.

**6,264** parcel-min of delay · **110** parcels late · **83 %** recoverable

*How we know: proven by 96 replays of this shift · error bars from 8 versions of the day.*

**Generated by** switchyard-analysis

## Summary

Body of the summary.

<details>
<summary><b>Impact</b> — 110 parcels late</summary>

## Impact

| Measure | Value |
|---|---|
| Delay | 6264 |

</details>

<details open>
<summary><b>Method</b> — how the numbers were made</summary>

## Method and confidence

- Replays.

</details>
`;

describe("splitReport", () => {
  const r = splitReport(REPORT);
  it("reads the headline card from the first four paragraphs", () => {
    expect(r.title).toBe("Post-mortem: demo (seed 1)");
    expect(r.card?.eyebrow).toBe("Incident 00:30–00:52 · up to 47 % below the fault-free twin");
    expect(r.card?.sentences).toEqual([
      "The C289 jam caused 70 % of the delay.",
      "The best fix is to send chute C289's destination to C269: it would have saved 83 %.",
    ]);
    expect(r.card?.stats).toEqual([
      { value: "6,264", caption: "parcel-min of delay" },
      { value: "110", caption: "parcels late" },
      { value: "83 %", caption: "recoverable" },
    ]);
    expect(r.card?.provenance).toContain("96 replays");
  });
  it("opens Summary, folds the details and drops their repeated headings", () => {
    expect(r.sections.map((s) => [s.title, s.open])).toEqual([
      ["Summary", true],
      ["Impact", false],
      ["Method", true],
    ]);
    expect(r.sections[0]!.body).toContain("Generated by");
    expect(r.sections[1]!.teaser).toBe("110 parcels late");
    expect(r.sections[1]!.body.startsWith("| Measure")).toBe(true);
  });
  it("gives no card when the report has no headline block", () => {
    const none = splitReport("# Post-mortem: x (seed 1)\n\n**Status:** no incident.\n");
    expect(none.card).toBeNull();
  });
  it("never keeps tags from the report", () => {
    const evil = splitReport("<details>\n<summary><b>A</b> — <img src=x onerror=alert(1)> t</summary>\nbody\n</details>");
    expect(evil.sections[0]!.teaser).toBe("t");
  });
});
